const updateModelSpec = `-- name: UpdateModelSpec :execrows
UPDATE model_specs SET
    display_name = COALESCE($1, display_name),
    description = COALESCE($2, description),
    kind = COALESCE($3, kind),
    context_window = COALESCE($4, context_window),
    max_output_tokens = COALESCE($5, max_output_tokens),
    input_cost_per_token = COALESCE($6::text::numeric, input_cost_per_token),
    output_cost_per_token = COALESCE($7::text::numeric, output_cost_per_token),
    cached_input_cost_per_token = COALESCE($8::text::numeric, cached_input_cost_per_token),
    cache_creation_input_cost_per_token = COALESCE($9::text::numeric, cache_creation_input_cost_per_token),
    default_context_strategy = COALESCE($10, default_context_strategy),
    is_active = COALESCE($11, is_active),
    updated_at = CASE WHEN $12::bool THEN $13 ELSE updated_at END
WHERE id = $14 AND workspace_id = $15
`

type UpdateModelSpecParams struct {
	DisplayName            pgtype.Text
	Description            pgtype.Text
	Kind                   pgtype.Text
	ContextWindow          pgtype.Int4
	MaxOutputTokens        pgtype.Int4
	InputCost              pgtype.Text
	OutputCost             pgtype.Text
	CachedInputCost        pgtype.Text
	CacheCreationInputCost pgtype.Text
	DefaultContextStrategy pgtype.Text
	IsActive               pgtype.Bool
	Touch                  bool
	Now                    pgtype.Timestamp
	ID                     uuid.UUID
	WorkspaceID            string
}

// UpdateModelSpec writes the fields that are not null; updated_at moves
// only when touch (a value changed).
func (q *Queries) UpdateModelSpec(ctx context.Context, arg UpdateModelSpecParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateModelSpec,
		arg.DisplayName,
		arg.Description,
		arg.Kind,
		arg.ContextWindow,
		arg.MaxOutputTokens,
		arg.InputCost,
		arg.OutputCost,
		arg.CachedInputCost,
		arg.CacheCreationInputCost,
		arg.DefaultContextStrategy,
		arg.IsActive,
		arg.Touch,
		arg.Now,
		arg.ID,
		arg.WorkspaceID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

